-- title-slide.lua
-- Passes title-slide options through to the runtime script
-- (uoe-scripts.html), which applies them. The title slide's own markup is
-- generated by Quarto's own template rather than written by hand, so there
-- is no Pandoc node here for a Lua filter to attach a class to directly -
-- everything below is applied live, in the browser, the same way the
-- footer and logo already are elsewhere in this theme.
--
-- Options (document or extension YAML):
--   title-style: watermark | colour | plain   (default: watermark)
--   title-watermark-image: "img/xyz.png"      optional - defaults to a
--                                              placeholder shipped with the
--                                              theme (img/title-watermark-
--                                              default.png) - replace that
--                                              file, or set this, for your
--                                              own mark
--   title-watermark-size: <percent>           optional, as a percentage of
--                                              the slide's width (default 38)
--   title-watermark-opacity: <0-1>            optional (default 0.08)
--   title-watermark-inset: <css length>       optional, gap kept from the
--                                              right edge (default 70px)
--   title-watermark-vpos: <percent>           optional, vertical anchor from
--                                              the top of the slide (default 35%)
--   event: "<text>"            optional, shown above the date
--   qrcode: "<url>"            adds a QR code to the title slide, linking here
--   qrcode-caption: "<text>"   optional caption under the QR code
--   qrcode-size: <px>          optional side length, design-space px (default 150)
--   qrcode-offset-x: <css length>  optional, extra gap from the right edge
--   qrcode-offset-y: <css length>  optional, extra gap from the bottom edge

local function meta_str(doc, key)
  local v = doc.meta[key]
  return v and pandoc.utils.stringify(v) or nil
end

local function js_escape(s)
  return (s:gsub("\\", "\\\\"):gsub("'", "\\'"):gsub("\n", "\\n"):gsub("\r", "\\r"):gsub("</", "<\\/"))
end

-- Appends `window.<jsName> = '<value>';\n` to `script` when `value` is a
-- non-empty string; otherwise returns `script` unchanged. Keeps the
-- (many, similarly-shaped) optional settings below to one line each.
local function set_if(script, jsName, value)
  if value and value ~= '' then
    return script .. 'window.' .. jsName .. ' = \'' .. js_escape(value) .. '\';\n'
  end
  return script
end

function Pandoc(doc)
  if not quarto.doc.is_format("revealjs") then
    return doc
  end

  local style = meta_str(doc, 'title-style') or 'watermark'
  if style ~= 'watermark' and style ~= 'colour' and style ~= 'plain' then
    style = 'watermark'
  end

  local watermark_image = meta_str(doc, 'title-watermark-image')
  local event = meta_str(doc, 'event')
  local qrcode_url = meta_str(doc, 'qrcode')

  local script = '<script>\nwindow.uoeTitleStyle = \'' .. js_escape(style) .. '\';\n'

  if style == 'watermark' then
    if watermark_image then
      script = set_if(script, 'uoeTitleWatermarkImage', watermark_image)
    else
      -- A placeholder shipped with the theme (img/UoE_CentredLogo_CMYK_roundel.png), 
      -- referenced the same way `logo:`/`footer-logo:`
      -- already are in _extension.yml - a path relative to the extension's
      -- own install location (_extensions/jpmorr/uoe-revealjs/...), which is how
      -- Quarto itself writes those two out in the compiled page, confirmed
      -- by checking the actual rendered HTML rather than assumed.
      --
      -- An earlier version of this tried quarto.doc.add_html_dependency's
      -- `resources` field instead, copying the file into a per-DOCUMENT
      -- folder (<doc-stem>_files/libs/...) with no reference written
      -- automatically (unlike its `scripts`/`stylesheets` fields, which do
      -- write one). Hand-writing that reference meant guessing the per-
      -- document folder name, which depends on each document's own
      -- filename and can't be known here - confirmed broken by rendering
      -- and checking the actual failed network request, not assumed
      -- correct from the file merely being copied successfully.
      script = set_if(script, 'uoeTitleWatermarkDefault', '_extensions/jpmorr/uoe-revealjs/img/UoE_CentredLogo_CMYK_roundel.png')
    end
    script = set_if(script, 'uoeTitleWatermarkSize', meta_str(doc, 'title-watermark-size'))
    script = set_if(script, 'uoeTitleWatermarkOpacity', meta_str(doc, 'title-watermark-opacity'))
    script = set_if(script, 'uoeTitleWatermarkInset', meta_str(doc, 'title-watermark-inset'))
    script = set_if(script, 'uoeTitleWatermarkVpos', meta_str(doc, 'title-watermark-vpos'))
  end

  script = set_if(script, 'uoeEvent', event)

  if qrcode_url then
    local caption = js_escape(meta_str(doc, 'qrcode-caption') or '')
    local size = js_escape(meta_str(doc, 'qrcode-size') or '')
    local offset_x = js_escape(meta_str(doc, 'qrcode-offset-x') or '')
    local offset_y = js_escape(meta_str(doc, 'qrcode-offset-y') or '')
    script = script .. 'window.uoeQrcode = {url: \'' .. js_escape(qrcode_url) ..
        '\', caption: \'' .. caption .. '\', size: \'' .. size ..
        '\', offsetX: \'' .. offset_x .. '\', offsetY: \'' .. offset_y .. '\'};\n'
  end

  script = script .. '</script>\n'
  quarto.doc.include_text('after-body', script)

  if qrcode_url then
    quarto.doc.add_html_dependency({
      name = 'uoe-qrcode',
      version = '1.0.0',
      scripts = { 'js/qrcode.min.js' },
    })
  end

  return doc
end